const settings = $input.first().json;
const topics = String(settings.searchTopics || '')
  .split(',')
  .map((topic) => topic.trim())
  .filter(Boolean);

if (topics.length === 0) {
  throw new Error('Digest settings has no topics. Put at least one topic in searchTopics, separated by commas.');
}

return topics.map((topic) => ({
  json: {
    topic,
    lookbackDays: settings.lookbackDays,
    articleCount: settings.articleCount,
  },
}));

parameters.text:
=You are preparing the section of a morning news digest that covers one topic: {{ $json.topic }}

Call the Webz.io news search tool exactly once, with these arguments:

- query: {{ $json.topic }}
- days: {{ $json.lookbackDays }}
- language: ["english"]
- k: {{ $json.articleCount }}

Do not pass any other filters.

From what the tool returns, pick up to 5 of the most significant stories. For each story provide the headline, the publisher, one sentence on why it matters, and the URL, exactly as the required output format specifies. Set the topic field to: {{ $json.topic }}

If the tool returns no usable articles, return an empty stories array.

parameters.jsCode:
const settings = $('Digest settings').first().json;
const clean = (value) => String(value ?? '').replace(/[<>|]/g, '').trim();

const seenUrls = new Set();
const sections = [];
const stories = [];
const today = new Date().toISOString().slice(0, 10);

for (const item of $input.all()) {
  const output = item.json.output || {};
  const topic = clean(output.topic) || 'News';
  const topicStories = Array.isArray(output.stories) ? output.stories : [];
  const lines = [];

  for (const story of topicStories) {
    const url = String(story?.url ?? '').trim();
    if (!url || seenUrls.has(url)) continue;
    seenUrls.add(url);

    const headline = clean(story.headline) || url;
    const publisher = clean(story.publisher);
    const why = clean(story.why_it_matters);

    let line = '• <' + url + '|' + headline + '>';
    if (publisher) line += ' — ' + publisher;
    if (why) line += '\n    ' + why;
    lines.push(line);

    stories.push({ date: today, topic, headline, publisher, why_it_matters: why, url });
  }

  if (lines.length > 0) {
    sections.push('*' + topic + '*\n' + lines.join('\n'));
  }
}

const digestText = ':newspaper: *Daily news digest — ' + today + '*\n\n' + sections.join('\n\n');

return [{
  json: {
    hasStories: stories.length > 0,
    digestText,
    stories,
    slackChannel: settings.slackChannel,
  },
}];
